import{_ as a,o as e,c as r,a4 as d}from"./chunks/framework.CzJ_HCFe.js";const l=JSON.parse('{"title":"The 30 Muhurtas — reference table (source of record)","description":"","frontmatter":{},"headers":[],"relativePath":"reference/07-muhurta-table.md","filePath":"reference/07-muhurta-table.md","lastUpdated":1788532705000}'),i={name:"reference/07-muhurta-table.md"};function s(o,t,n,u,h,c){return e(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="the-30-muhurtas-—-reference-table-source-of-record" tabindex="-1">The 30 Muhurtas — reference table (source of record) <a class="header-anchor" href="#the-30-muhurtas-—-reference-table-source-of-record" aria-label="Permalink to &quot;The 30 Muhurtas — reference table (source of record)&quot;">​</a></h1><p>This is the verified reference for the named-muhurta system the muhurta finder is being rebuilt on. <strong>Do not edit values without owner sign-off</strong> — every cell here is either owner-confirmed or web-sourced, tagged below.</p><h2 id="what-a-muhurta-is" tabindex="-1">What a muhurta is <a class="header-anchor" href="#what-a-muhurta-is" aria-label="Permalink to &quot;What a muhurta is&quot;">​</a></h2><p>A <strong>muhurta</strong> is 1/30 of the ahorātra (day-and-night): <strong>15 daytime</strong> muhurtas from sunrise to sunset, <strong>15 night</strong> muhurtas from sunset to the next sunrise. Each is ≈48 minutes (2 ghati) at the equinox but is computed <strong>proportionally</strong> — daytime÷15 and night÷15 — so it expands and contracts with the season. Each muhurta has a name, most have a presiding deity, and each has an intrinsic auspicious/inauspicious nature.</p><p>This is a <strong>different system from choghadiya</strong> (the 8-fold day/night division). Both are kept, as scoring inputs — see &quot;Scoring model&quot; below.</p><h2 id="computation" tabindex="-1">Computation <a class="header-anchor" href="#computation" aria-label="Permalink to &quot;Computation&quot;">​</a></h2><ul><li><strong>Daytime muhurta length</strong> = (sunset − sunrise) / 15; the <em>i</em>-th daytime muhurta runs sunrise + (i−1)·len … sunrise + i·len.</li><li><strong>Night muhurta length</strong> = (next sunrise − sunset) / 15; analogous from sunset.</li><li>The engine already computes this division (<code>_durmuhurtham</code>, <code>_abhijit_muhurta</code> in <code>engines/base.py</code>). The finder will reuse it rather than re-slice.</li><li><strong>Abhijit</strong> = the <strong>8th daytime</strong> muhurta (straddles solar noon); <strong>none on Wednesday</strong> (engine already encodes this).</li><li><strong>Brahma</strong> = the <strong>14th night</strong> muhurta (pre-dawn). Traditionally also given as a fixed 1/30-of-24h window; the engine&#39;s existing Brahma definition stands.</li></ul><h2 id="daytime-muhurtas-from-sunrise" tabindex="-1">Daytime muhurtas (from sunrise) <a class="header-anchor" href="#daytime-muhurtas-from-sunrise" aria-label="Permalink to &quot;Daytime muhurtas (from sunrise)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>Muhurta</th><th>Presiding deity</th><th>Nature</th></tr></thead><tbody><tr><td>1</td><td>Rudra</td><td>Rudra (fierce Śiva)</td><td>inauspicious</td></tr><tr><td>2</td><td>Ahi</td><td>Sarpa / the Serpent (Nāga)</td><td>inauspicious</td></tr><tr><td>3</td><td>Mitra</td><td>Mitra (Āditya)</td><td>auspicious</td></tr><tr><td>4</td><td>Pitri</td><td>the Pitṛs (ancestors)</td><td>inauspicious</td></tr><tr><td>5</td><td>Vasu</td><td>the Vasus</td><td>auspicious</td></tr><tr><td>6</td><td>Vara</td><td>Varāha (boar avatar of Viṣṇu)</td><td>auspicious</td></tr><tr><td>7</td><td>Vishvedeva</td><td>the Viśvedevas</td><td>auspicious</td></tr><tr><td>8</td><td>Vidhi (<strong>Abhijit</strong>)</td><td>Brahmā</td><td>auspicious (most; none on Wed)</td></tr><tr><td>9</td><td>Sathamukhi</td><td>— (concept: &quot;fair-faced&quot;)</td><td>auspicious</td></tr><tr><td>10</td><td>Puruhuta</td><td>Indra (Puruhūta)</td><td>inauspicious</td></tr><tr><td>11</td><td>Vahini</td><td>— (concept: &quot;carrier/host&quot;)</td><td>inauspicious</td></tr><tr><td>12</td><td>Naktanchara</td><td>— (concept: &quot;night-wanderer&quot;)</td><td>inauspicious</td></tr><tr><td>13</td><td>Varuna</td><td>Varuṇa</td><td>auspicious</td></tr><tr><td>14</td><td>Aryama</td><td>Aryaman (Āditya)</td><td>auspicious</td></tr><tr><td>15</td><td>Bhaga</td><td>Bhaga (Āditya)</td><td>inauspicious</td></tr></tbody></table><h2 id="night-muhurtas-from-sunset" tabindex="-1">Night muhurtas (from sunset) <a class="header-anchor" href="#night-muhurtas-from-sunset" aria-label="Permalink to &quot;Night muhurtas (from sunset)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>Muhurta</th><th>Presiding deity</th><th>Nature</th></tr></thead><tbody><tr><td>1</td><td>Girisha</td><td>Śiva (Girīśa)</td><td>inauspicious</td></tr><tr><td>2</td><td>Ajapada</td><td>Aja-Ekapāda (a Rudra)</td><td>inauspicious</td></tr><tr><td>3</td><td>Ahirbudhnya</td><td>Ahirbudhnya (a Rudra)</td><td>auspicious</td></tr><tr><td>4</td><td>Pusha</td><td>Pūṣan (Āditya)</td><td>auspicious</td></tr><tr><td>5</td><td>Aswi</td><td>the Aśvins</td><td>auspicious</td></tr><tr><td>6</td><td>Yama</td><td>Yama</td><td>inauspicious</td></tr><tr><td>7</td><td>Agni</td><td>Agni</td><td>inauspicious</td></tr><tr><td>8</td><td>Vidhatru</td><td>Vidhātṛ (the ordainer)</td><td>auspicious</td></tr><tr><td>9</td><td>Chanda</td><td>Chandra (Moon)</td><td>auspicious</td></tr><tr><td>10</td><td>Aditi</td><td>Aditi</td><td>auspicious</td></tr><tr><td>11</td><td>Jeeva</td><td>Bṛhaspati (Jupiter)</td><td>auspicious (most)</td></tr><tr><td>12</td><td>Vishnu</td><td>Viṣṇu</td><td>auspicious</td></tr><tr><td>13</td><td>Yumigadyuti</td><td>— (concept: &quot;brilliance of light&quot;)</td><td>auspicious</td></tr><tr><td>14</td><td><strong>Brahma</strong></td><td>Brahmā</td><td>auspicious (most; Brahma Muhurta)</td></tr><tr><td>15</td><td>Samudra</td><td>— (concept: &quot;ocean&quot;)</td><td>auspicious</td></tr></tbody></table><p>Intrinsically inauspicious set: <strong>day</strong> 1, 2, 4, 10, 11, 12, 15; <strong>night</strong> 1, 2, 6, 7. (These are distinct from the weekday-specific Durmuhurtam the engine already computes — see Scoring model.)</p><h2 id="scoring-model-owner-confirmed" tabindex="-1">Scoring model (owner-confirmed) <a class="header-anchor" href="#scoring-model-owner-confirmed" aria-label="Permalink to &quot;Scoring model (owner-confirmed)&quot;">​</a></h2><p>The finder is an <strong>honest, additive scoring system</strong> — it does not pick one tradition over another; every applicable factor contributes and is disclosed to the user. For a chosen activity, a muhurta&#39;s score layers:</p><ol><li><strong>Intrinsic muhurta nature</strong> (this table) — auspicious/inauspicious base.</li><li><strong>Weekday Durmuhurtam</strong> (engine <code>DURMUHURTA_DAY_MUHURTAS</code>) — an <em>additional</em> penalty on the specific muhurta(s) inauspicious for that weekday. Additive, not an override.</li><li><strong>Choghadiya</strong> (Amrit/Shubh/… — the 8-fold system) — kept as a scoring attribute of the muhurta it falls in.</li><li><strong>Tarabalam / Chandrabalam / lagna / tithi-class / special yogas</strong> — as already implemented.</li></ol><p><strong>&quot;Good for [event]&quot; is not a per-muhurta attribute</strong> — it is answered by the finder&#39;s source-profile activity catalogue (<code>ACTIVITY_RULES</code>): the user selects the event (wedding, gruhapravesha, travel, surgery, …) and the finder scores muhurtas for it. No per-muhurta activity list is invented.</p><h2 id="provenance" tabindex="-1">Provenance <a class="header-anchor" href="#provenance" aria-label="Permalink to &quot;Provenance&quot;">​</a></h2><ul><li><strong>Muhurta names (all 30) + Brahma at night-14</strong> — owner-confirmed (B.V. Raman, <em>Muhurtha</em>).</li><li><strong>Chanda deity (Moon) + nature (auspicious)</strong> — owner-ruled.</li><li><strong>Vara → Varāha; Yumigadyuti, Samudra natures</strong> — web-sourced.</li><li><strong>Day natures; night natures (except Chanda)</strong> — web-sourced, consistent across sources; pending final owner read.</li><li><strong>Deity-vs-concept distinction</strong> — several names are abstractions, not deities (Taittirīya-brāhmaṇa, per wisdomlib); a blank deity cell is intentional, not missing data.</li></ul><p>Sources: B.V. Raman <em>Muhurtha</em>; wisdomlib.org/definition/muhurta; onlinejyotish.com; ganeshmitra.co.in/30-muhurta; instaastro.com/muhurat; chamundaswamiji.com; anustubhblog.wordpress.com.</p>',19)])])}const g=a(i,[["render",s]]);export{l as __pageData,g as default};
